'use client';
import Link from 'next/link';
import { ArrowUpRight, ArrowRight, Printer, ChevronDown, BookOpen, Library, ExternalLink } from 'lucide-react';
import { books } from '@/data/books';
import { topicMap } from '@/data';
import type { Book } from '@/lib/types';
import { PageHeading, InfoNote, BookmarkButton } from './ui';

export function BookCover({ book }: { book: Book }) { return <div className={`book-cover ${book.color}`}><span className="book-cover-code">{book.code}</span><h2>{book.title}</h2><span className="book-cover-author">{book.authors}</span><div className="book-cover-orbit" /></div>; }
export default function ReadingRoom() {
  return <div className="page-enter"><PageHeading eyebrow="FIVE BOOKS. A WIDER PERSPECTIVE." title="Good questions have a reading list." description="The five books in your syllabus, connected to the lessons, cases, and ideas they help you understand."><Link href="/print?scope=library" className="button button-secondary"><Printer size={16} />Print reading guides</Link></PageHeading><div className="book-shelf">{books.map(book => <Link className="book-card" href={`/library/${book.id}`} key={book.id}><BookCover book={book} /><div className="book-card-info"><p>{book.year} · {book.publisher}</p><h3>{book.authors}</h3><div><span>{book.chapters.length} reading sections</span><span className="text-link">Open guide<ArrowUpRight size={14} /></span></div></div></Link>)}</div><div className="reading-note"><InfoNote><strong>A guide to the books, not a copy of them.</strong> Read the original works through your library or the publisher. These original study notes connect the readings to your syllabus; page numbers and chapter organization depend on the edition. Historical legal references are supplemented throughout the course.</InfoNote></div></div>;
}
export function BookReader({ book }: { book: Book }) {
  return <div className="page-enter"><Link className="back-link" href="/library"><Library size={15} />Back to the reading room</Link><div className="book-reader-header"><BookCover book={book} /><div><span className="tag tag-teal">SYLLABUS READING GUIDE</span><h1>{book.title}</h1><p className="book-byline">{book.authors}</p><p>{book.year} · {book.publisher}</p><p>{book.description}</p><div className="heading-actions"><a href={book.url} target="_blank" rel="noopener noreferrer" className="button button-primary">Publisher’s edition<ExternalLink size={14} /></a><BookmarkButton id={`book:${book.id}`} label /><Link href={`/print?book=${book.id}`} className="button button-secondary"><Printer size={15} />Print guide</Link></div></div></div><div className="book-edition-note"><InfoNote warning={book.id === 'benild' || book.id === 'casey'}>{book.editionNote}</InfoNote></div><div className="section-heading"><div><span className="eyebrow">READ WITH A QUESTION IN MIND</span><h2>Your chapter connections.</h2></div><span className="tag tag-muted">{book.chapters.length} study sections</span></div><div className="chapter-list">{book.chapters.map((chapter, index) => <details className="chapter-card" key={chapter.title} open={index === 0}><summary><span>{String(index + 1).padStart(2, '0')}</span><h3>{chapter.title}</h3><ChevronDown size={17} /></summary><div className="chapter-card-body"><p>{chapter.summary}</p><div className="chapter-topic-links">{chapter.topics.map(id => <Link href={`/topics/${id}`} key={id}><BookOpen size={12} />{id} · {topicMap[id]?.title}<ArrowRight size={12} /></Link>)}</div></div></details>)}</div></div>;
}
